import csv
import io
import json

FIELDS = ("id", "name")


def _normalize(rows):
    """Yield new dicts with only the export fields; '' for missing/None, str() otherwise."""
    for row in rows:
        clean = {}
        for key in FIELDS:
            value = row.get(key)
            clean[key] = "" if value is None else str(value)
        yield clean


def _to_csv(rows):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(FIELDS)
    for row in rows:
        writer.writerow([row[key] for key in FIELDS])
    return buffer.getvalue()


def _to_json(rows):
    return json.dumps(list(rows), ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {"csv": _to_csv, "json": _to_json}


def export_rows(rows, format):
    try:
        serializer = _SERIALIZERS[format]
    except (KeyError, TypeError):
        raise ValueError("unsupported format") from None
    return serializer(_normalize(rows))

